ROOMS = [
    {"name": "attic", "sqm": 12, "ensuite": True, "balcony": False},
    {"name": "back", "sqm": 10, "ensuite": False, "balcony": False},
    {"name": "front", "sqm": 14, "ensuite": False, "balcony": True},
